<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require __DIR__.'/app/customer.php';require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$label=trim($_POST['client_label']??'');if($name===''){flash('Informe o nome do projeto.','error');}else{$q=db()->prepare("INSERT INTO projects(name,description,client_label) VALUES(?,?,?)");$q->execute([$name,$desc?:null,$label?:null]);flash('Projeto criado.');}header('Location: projects.php');exit;}
$rows=db()->query("SELECT pr.*,(SELECT COUNT(*) FROM plaques p WHERE p.project_id=pr.id) plaques_count,(SELECT COUNT(*) FROM companies c WHERE c.project_id=pr.id) companies_count FROM projects pr ORDER BY pr.created_at DESC")->fetchAll();
layout_start('Projetos');
?><div class="heading"><div><h1>Projetos</h1><p>Organize placas por cliente, campanha ou unidade.</p></div></div><form method="post" class="panel"><?=client_csrf_field()?><div class="formgrid"><label>Nome do projeto *<input name="name" placeholder="Ex.: Clínica São Lucas" required></label><label>Cliente / campanha<input name="client_label" placeholder="Ex.: Unidade Centro"></label><label class="full">Descrição<input name="description"></label></div><button>Criar projeto</button></form><section class="panel"><h2>Projetos cadastrados</h2><div class="tablewrap"><table><thead><tr><th>Projeto</th><th>Cliente/campanha</th><th>Placas</th><th>Empresas</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><br><small><?=e($r['description']??'')?></small></td><td><?=e($r['client_label']??'—')?></td><td><?=$r['plaques_count']?></td><td><?=$r['companies_count']?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Nenhum projeto cadastrado.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>